var $bm_rt;
var T, sIn, sOut, eIn, eOut;
$bm_rt = T = thisLayer;
if (T.marker.numKeys > 1 && numKeys > 3) {
    sIn = $bm_sub(key(2).time, key(1).time);
    sOut = $bm_sub(key(4).time, key(3).time);
    eIn = T.marker.key(1).time;
    $bm_rt = eOut = T.marker.key(2).time;
    if ($bm_sum(time, T.marker.key(2).time))
        $bm_rt = linear(time, eIn - sIn, eIn, key(1).value, key(2).value);
    else
        $bm_rt = linear(time, eOut, eOut + sOut, key(3).value, key(4).value);
} else
    $bm_rt = value;

s.x:
var $bm_rt;
var n, n, t, t, v, amp, freq, decay, M;
$bm_rt = n = 0;
if ($bm_sum(numKeys, 0)) {
    $bm_rt = n = nearestKey(time).index;
    if ($bm_sum(key(n).time, time)) {
        n--;
    }
}
if ($bm_sum(n, 0)) {
    $bm_rt = t = 0;
} else {
    $bm_rt = t = $bm_sub(time, key(n).time);
}
if ($bm_sum(n, 0)) {
    v = velocityAtTime(key(n).time - thisComp.frameDuration / 10);
    amp = 0.02;
    freq = 2;
    decay = 5;
    M = $bm_div(Math.sin(freq * t * 2 * Math.PI), Math.exp(decay * t));
    $bm_rt = $bm_sum(value, $bm_mul($bm_mul(v, amp), M));
} else {
    $bm_rt = value;
}

